        var isActive = curTypeFilter === t.key;
        out += `<div class="bar-row" onclick="state.filters.tenantType=(state.filters.tenantType==='` + t.key + "' ? '':'" + t.key + `');render()"` + (isActive ? ' style="background:var(--gray-50)"' : "") + '><span class="bar-row__icon">' + t.icon + '</span><div class="bar-row__body"><div class="bar-row__top"><span class="bar-row__label">' + t.key + '</span><span class="bar-row__value">' + s.occ + "/" + s.total + " \xB7 " + pct2 + '%</span></div><div class="bar-row__track"><div class="bar-row__fill" style="background:' + t.color + ";width:" + pct2 + '%"></div></div></div></div>';
